const taskQ = [];
const microQ = [];
function enqueueTask(fn) { taskQ.push(fn); }
function enqueueMicro(fn) { microQ.push(fn); }

// Two tasks land on the loop. The first task enqueues a microtask
// that itself enqueues another microtask — both must drain before task 2.
enqueueTask(() => {
  console.log('task1');
  enqueueMicro(() => {
    console.log('micro1a');
    enqueueMicro(() => console.log('micro1b'));
  });
});
enqueueTask(() => console.log('task2'));

tasks.solution:
function drainMicrotasks() {
  while (microQ.length) {
    const m = microQ.shift();
    m();
  }
}
function runLoop() {
  while (taskQ.length) {
    const task = taskQ.shift();
    task();
    drainMicrotasks();
  }
}
runLoop();

